const filtersPnd =  (arr, sub2) => {
    let pending = [];
    let sub = {...sub2};
    let verified = [];
    let rangDt = getStore("date_range_submayor");
    let comprobantesBanco = {...getStore("submayor_list")};

    let cmpOn2 = { }
    let cmpDuplicate = { }



    for(let i in arr){
        let hh =  arr[i];
        if(hh.date>=rangDt?.initDate && hh.date<=rangDt?.lastDate){
            if(hh.linkId && hh.status===9){
                verified.push(hh);
                if(cmpOn2[hh.linkId]){
                    cmpDuplicate[hh.bankRecordId] = hh;
                }
                else{
                    cmpOn2[hh.linkId] = 1;
                    if(comprobantesBanco[hh.linkId]){
                       delete comprobantesBanco[hh.linkId];
                    }
                }
                delete sub[hh.linkId];
            }
            else{
                pending.push(hh);
            }
        }
    }

    
    let bankSubLeft = [];
    let bankSubLeft_wZr = [];

    for(let i in comprobantesBanco){
        let amm = comprobantesBanco[i].amount * 1;
        if(amm!==0){
            bankSubLeft.push(comprobantesBanco[i]);
        }else{
            bankSubLeft_wZr.push(comprobantesBanco[i]);
        }
    }

    return {
        pending:sortSubAccounts(pending,"date"),
        verified:sortSubAccounts(verified,"date"),
        sub_mayor: sortByDate(convertObj2Array(sub),"date"),
        verified_duplicatedLink: cmpDuplicate,
        bankSubLeft: bankSubLeft,
        bankSubLeft_wZr:bankSubLeft_wZr
    };
}



function convertArray2ObjGroupby(arr1, key) {
    key = key ? key : "id";
    var obj = {};
    if (arr1.length > 0) {
            arr1.map((s) => {
                if(s.subAccount){
                    if (!obj[s[key]]) {
                    obj[s[key]] = [];
                    }
                    obj[s[key]].push(s);
                }
            });
    } else {
      obj = null;
    }
    return obj;
  }




