export function GroupbyAcc(arr, isPay) {
    
    var obj = {
        "operations":[]
    };

    let arr1 = arr && ObjectKeys(arr)
    if (arr1.length > 0) {
      arr1.map((ele) => {
        let s = arr[ele];
        if(s["type"]){
            obj["operations"].push(convert4acc(s));
        }
      });
    } else {
      obj = null;
    }
    return obj;
  }






  export function convert4acc(s) {
    let nItm = {};
    let accc = getStore("account_ids")?.[s["account"]];
    nItm["account"] =  accc
    nItm["sub_account"] = getStore("sub_account_ids")?.[s["subAccount"]];
    nItm["comprobanteId"] = s["comprobanteId"];
    nItm["operationId"] = s["operationId"];
    nItm["document"] = s["document"];
    nItm["description"] = s["description"];
    nItm["date"] = s["date"];



    if(s["type"]==="credit"){
        nItm["debit"] = 0;
        nItm["credit"] = s["amount"];
    }
    else if(s["type"]==="debit"){
        nItm["credit"] = 0;
        nItm["debit"] = s["amount"];
    }
    return nItm;
  }



  
