export const sortAccounts = (td, key) =>
callbackOnMemory(
	"sortAccounts",
	[td, key],
	() => {
        let order = true;
		let sortedA = td && td.sort((a, b) => {
			let A = a[key] * 1;
			let B = b[key] *1;
			if (A < B) {
				return order ? -1 : 1;
			}
			if (A > B) {
				return order ? 1 : -1;
			}
			return 0;
        });
		return sortedA;
	}
);


